import{_ as s,C as t,c as n,o,j as i,ak as p,a as l,G as d}from"./chunks/framework.HpAH9DIy.js";const y=JSON.parse('{"title":"连接问题","description":"","frontmatter":{},"headers":[],"relativePath":"FAQ/04-connection-issues.md","filePath":"zh/FAQ/04-connection-issues.md","lastUpdated":1774343196000}'),h={name:"FAQ/04-connection-issues.md"},r={id:"连接问题",tabindex:"-1"};function c(u,a,k,g,m,b){const e=t("Badge");return o(),n("div",null,[i("h1",r,[a[0]||(a[0]=l("连接问题")),d(e,{type:"danger",text:"问题"}),a[1]||(a[1]=l()),a[2]||(a[2]=i("a",{class:"header-anchor",href:"#连接问题","aria-label":'Permalink to "连接问题<Badge type="danger" text="问题" />"'},"​",-1))]),a[3]||(a[3]=p(`<div class="danger custom-block"><p class="custom-block-title">危险</p><p>使用<code>MaaYuan</code>前，请确认是否已自行安装并打开模拟器。</p></div><h2 id="模拟器设置" tabindex="-1">模拟器设置 <a class="header-anchor" href="#模拟器设置" aria-label="Permalink to &quot;模拟器设置&quot;">​</a></h2><ul><li><p>关闭模拟器后台保活；</p></li><li><p>模拟器旧版本可能连接不上，请更新模拟器</p></li><li><p>手动打开模拟器→启动游戏→游戏内（能看见游戏头像与昵称的页面）打开<code>MaaYuan</code>。</p></li><li><p>不同模拟器的设置</p><ul><li><p>雷电模拟器，请调整模拟器分辨率，版本可升级至9.0.37以及以上；</p></li><li><p>夜神模拟器，请切换触控模式：<code>MaaYuan</code>设置-触控模式-选择“<em>AutoDetect</em>（自动检测）”</p></li><li><p>蓝叠模拟器</p><ul><li><p>请下载 “<a href="https://wwsq.lanzoue.com/i0Yhg2gk5czg" target="_blank" rel="noreferrer">蓝叠adb tools</a> ” 并解压，将其地址手动填写至adb路径</p></li><li><p>检查是否打开了adb连接：<code>设置</code> - <code>高级</code> - <code>Android调试（ADB）</code></p></li></ul></li></ul></li></ul><details class="details custom-block"><summary>MuMu 模拟器相关文档</summary><ul><li>WIN系统-MuMu模拟器：<a href="https://mumu.163.com/help/20240807/40912_1073151.html" target="_blank" rel="noreferrer">MuMu模拟器如何连接 adb？_MuMu模拟器_安卓模拟器</a></li><li>MAC系统-MuMu模拟器Pro：<a href="https://mumu.163.com/mac/tutorials/connect-adb.html" target="_blank" rel="noreferrer">如何连接ADB？_MuMu模拟器_安卓模拟器</a></li><li><a href="https://mumu.163.com/help/20240807/40912_1073151.html" target="_blank" rel="noreferrer">MuMu模拟器12如何连接adb</a></li><li><a href="https://mumu.163.com/help/20240807/40912_1144608.html" target="_blank" rel="noreferrer">使用UU加速器后无法通过ADB连接MuMu12</a></li><li><a href="https://mumu.163.com/help/20240807/40912_1164744.html" target="_blank" rel="noreferrer">MuMu模拟器桥接模式连接adb教程</a></li><li><a href="https://mumu.163.com/help/20240902/40912_1178199.html" target="_blank" rel="noreferrer">MuMu模拟器12adb远程调试功能教程</a></li></ul></details><h2 id="更新过后连不上模拟器" tabindex="-1">更新过后连不上模拟器 <a class="header-anchor" href="#更新过后连不上模拟器" aria-label="Permalink to &quot;更新过后连不上模拟器&quot;">​</a></h2><ul><li>提示资源加载失败 → 删除现有<code>MaaYuan</code>文件夹，重新下载/解压</li><li>能搜到模拟器 → 点【自定义】→【保存】</li><li>搜不到模拟器 → 重启（按顺序尝试）：<code>MaaYuan</code>→ 模拟器 → 电脑</li><li>ADB异常 → 强制关闭ADB工具后重新搜索</li></ul><h2 id="对-adb-exe-路径的访问被拒绝" tabindex="-1">对“adb.exe”路径的访问被拒绝 <a class="header-anchor" href="#对-adb-exe-路径的访问被拒绝" aria-label="Permalink to &quot;对“adb.exe”路径的访问被拒绝&quot;">​</a></h2><p>可能原因：</p><ul><li>ADB路径/文件检测错误（自动检测时）；</li><li>无权限访问ADB或相关文件；</li><li>硬盘故障导致文件访问重定位失败。</li></ul><p>解决办法：</p><ul><li>手动替换ADB；</li><li>改用自定义连接。</li></ul><h2 id="adb被占用" tabindex="-1">ADB被占用 <a class="header-anchor" href="#adb被占用" aria-label="Permalink to &quot;ADB被占用&quot;">​</a></h2><p>常见原因及处理</p><ul><li>手机助手占用：关闭手机助手及后台进程</li><li>多开冲突：检查是否被其他<code>MaaYuan</code>/游戏占用</li><li>残留进程：通过任务管理器结束所有<code>adb</code>相关进程后重试</li></ul><p>基础解决步骤 关闭<code>MaaYuan</code>→ 打开任务管理器（Ctrl+Shift+Esc）→ 结束所有名称含<code>adb</code>的进程→ 重启<code>MaaYuan</code>，若仍失败，下载运行工具：<code>如果提示adb文件被占用请打开我.bat</code></p><details class="details custom-block"><summary>高级排查（日志报错时）</summary><p>典型错误特征：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: cannot bind to 127.0.0.1:5037（端口占用）</span></span>
<span class="line"><span>adb server version不匹配</span></span></code></pre></div><p><strong>定位占用程序：</strong></p><ul><li><p>按<code>Win+R</code>输入<code>cmd</code>回车</p></li><li><p>执行命令（示例）：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findstr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5037</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # ADB守护端口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findstr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5555</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 模拟器常用端口</span></span></code></pre></div></li><li><p>记录输出中的<code>PID</code>（末尾数字）</p></li><li><p>在任务管理器（需开启PID显示）找到对应PID进程，结束可疑程序</p></li></ul><p><strong>附：开启任务管理器PID显示</strong></p><ul><li>右键任务管理器表头 → 勾选<code>PID</code></li></ul></details><h2 id="关闭外置vpn" tabindex="-1">关闭外置VPN <a class="header-anchor" href="#关闭外置vpn" aria-label="Permalink to &quot;关闭外置VPN&quot;">​</a></h2><ul><li>部分加速器在启动加速和停止加速之后，都需要重启<code>MaaYuan</code>、Adb 和模拟器再连接。</li><li>同时使用 UU 加速器 和 MuMu 12 可以参考<a href="https://mumu.163.com/help/20240321/35047_1144608.html" target="_blank" rel="noreferrer"><strong>官方文档</strong></a>。</li><li>MuMu12模拟器支持内置加速功能，无需外置加速。</li></ul><h2 id="确认-adb-及连接地址正确" tabindex="-1">确认 Adb 及连接地址正确 <a class="header-anchor" href="#确认-adb-及连接地址正确" aria-label="Permalink to &quot;确认 Adb 及连接地址正确&quot;">​</a></h2><p>自动连接检测失败</p><ul><li><p>尝试以管理员权限启动<code>MaaYuan</code>（右键<code>MaaYuan.exe</code>，选以管理员身份运行）再检测；</p></li><li><p>仍失败，参考手动设置，确认模拟器和连接地址在下方列表。</p></li><li><p>支持设备及地址：</p><details class="details custom-block"><summary>查看常见连接地址</summary><ul><li>BlueStacks 5：<code>127.0.0.1:5555/5556/5565/5575/5585/5595/5554</code></li><li>MuMu 模拟器 12：<code>127.0.0.1:16384/16416/16448/16480/16512/16544/16576</code></li><li>雷电模拟器 9：<code>emulator-5554/5556/5558/5560</code>, <code>127.0.0.1:5555/5557/5559/5561</code></li><li>夜神模拟器：<code>127.0.0.1:62001/59865</code></li><li>逍遥模拟器：<code>127.0.0.1:21503</code></li></ul></details></li></ul><p>手动连接设置</p><ul><li><p>填写信息：<code>MaaYuan</code>主界面 - 右上角连接框内 - 点击自定义按钮，填 adb 地址及路径；</p></li><li><p>导入 ADB路径：点击 Adb 路径后的“导入”，在模拟器的安装路径中找到 adb 的 exe 文件（如 adb.exe），点击打开；</p></li><li><p>模拟器ADB地址：本机模拟器连接地址为 127.0.0.1:&lt;端口号&gt; 或 emulator-&lt;四位数字&gt;。</p></li><li><p>常见模拟器地址：</p><details class="details custom-block"><summary>查看常见模拟器地址</summary><ul><li>BlueStacks 5：<code>127.0.0.1:5555/5556/5565/5575/5585/5595/5554</code></li><li>MuMu 模拟器 12：<code>127.0.0.1:16384/16416/16448/16480/16512/16544/16576</code></li><li>雷电模拟器 9：<code>emulator-5554/5556/5558/5560</code>, <code>127.0.0.1:5555/5557/5559/5561</code></li><li>夜神模拟器：<code>127.0.0.1:62001/59865</code></li><li>逍遥模拟器：<code>127.0.0.1:21503</code></li></ul></details></li><li><p>替换Adb（解决连接/报错问题）：</p><ul><li>下载<a href="https://wwsq.lanzoue.com/i0Yhg2gk5czg" target="_blank" rel="noreferrer">platform tools</a>并解压到<strong>全英文路径</strong>；</li><li>打开<code>MaaYuan</code>设置 → 连接 → 点击Adb路径图标 → 选择解压文件夹内的<strong>adb.exe</strong>（<em>不可单独使用，需保留完整文件</em>）；</li><li><strong>重要</strong>：若用自定义连接，勿点“刷新”或“自动检测”（避免路径被重置）。</li></ul></li><li><p>防火墙问题：临时关闭防火墙，并将 <strong>adb.exe</strong> 加入白名单。</p></li><li><p>路径问题：确保<code>MaaYuan</code>和platform tools所在目录<strong>无中文/特殊字符</strong>（改用全英文路径）。</p></li></ul><h2 id="启动agent无进展" tabindex="-1">启动Agent无进展 <a class="header-anchor" href="#启动agent无进展" aria-label="Permalink to &quot;启动Agent无进展&quot;">​</a></h2><p>正在安装运行库，请稍候（通常10-15秒进入下一步）。若卡在“启动 Agent”无进展：</p><ul><li><p>重启尝试；</p></li><li><p>重新安装尝试：</p><ul><li>不给机会：删除当前报错的文件夹，前往导航站下载完整包，重新解压；</li><li>再给机会：选择设置-更新设置-重新下载资源全量包。</li></ul></li><li><p>Mac用户：可能因安全限制，可询问AI（如：“Mac上程序调用的嵌入式Python环境无法启动”）；</p></li><li><p>其他情况：关闭MuMu12模拟器支持内置加速功能，将<code>debug/maa.log</code>文件提供给AI排查并按指引操作。</p></li></ul><h2 id="依赖安装失败" tabindex="-1">依赖安装失败 <a class="header-anchor" href="#依赖安装失败" aria-label="Permalink to &quot;依赖安装失败&quot;">​</a></h2><p>如果显示<strong>依赖安装失败</strong>，请尝试手动安装依赖库。</p><ul><li><p><strong>手动安装依赖库方法：</strong></p><details class="details custom-block"><summary>查看手动安装步骤</summary><ul><li>注意终端内均为英文符号</li><li>win+R，输入cmd，回车打开终端</li><li>先输入<code>D:</code>/<code>E:</code>/<code>F:</code>，回车，切换到MaaYuan所在的盘。例如在D盘，则输入<code>D:</code>，回车</li><li><img src="https://docimg2.docs.qq.com/image/AgAABTTp4UWJHEwtrRdCJbAApElzBVcY.png?w=636&amp;h=273" alt="https://docimg2.docs.qq.com/image/AgAABTTp4UWJHEwtrRdCJbAApElzBVcY.png?w=636&amp;h=273"></li></ul><p>切换成功后，输入以下内容：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">D:\\MaaYuan-win-x86_64-v0.9.13-beta.7\\python\\python.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maafw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pandas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openpyxl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loguru</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencv-python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zhconv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pypi.tuna.tsinghua.edu.cn/simple</span></span></code></pre></div><p>注意：需要把<code>\\python</code>前面的内容改成自己 MaaYuan 所在的路径（能看到 <code>python</code> 文件夹的这一页）。</p><p>例如：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">D:\\麻园\\MaaYuan-win-x86_64-v0.9.13-beta.7\\python\\python.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maafw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pandas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openpyxl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loguru</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencv-python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zhconv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pypi.tuna.tsinghua.edu.cn/simple</span></span></code></pre></div><ul><li>输入完成后回车，耐心等待安装完毕。</li><li>之后打开<code>MaaYuan</code>，等待显示依赖安装成功即可。</li></ul></details></li><li><p>如果显示因网络问题失败，尝试将-i 后的地址更换其它镜像源，如：<code>https://mirrors.aliyun.com/pypi/simple</code></p></li><li><p>如果手动安装过程中遇到报错，可将报错内容复制发给AI让其分析解决方案。</p></li></ul>`,29))])}const B=s(h,[["render",c]]);export{y as __pageData,B as default};
